import{_ as r,o as n,c as a,a2 as t}from"./chunks/framework.D66Xq0Kv.js";const s="/images/agent-harness-blueprint.jpg",u=JSON.parse('{"title":"Harness Engineering：11 个编码 Agent 的解剖报告","description":"","frontmatter":{},"headers":[],"relativePath":"notes/agent-harness-paper.md","filePath":"notes/agent-harness-paper.md","lastUpdated":1791166316000}'),o={name:"notes/agent-harness-paper.md"};function i(l,e,g,d,h,p){return n(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="harness-engineering-11-个编码-agent-的解剖报告" tabindex="-1">Harness Engineering：11 个编码 Agent 的解剖报告 <a class="header-anchor" href="#harness-engineering-11-个编码-agent-的解剖报告" aria-label="Permalink to &quot;Harness Engineering：11 个编码 Agent 的解剖报告&quot;">​</a></h1><blockquote><p>📖 读书笔记 · 信息来源：X 用户 <a href="https://x.com/undefinedKi" target="_blank" rel="noreferrer">Yarchi（@undefinedKi）</a> 2026-10-03 的<a href="https://x.com/undefinedKi/status/2106479763636302271" target="_blank" rel="noreferrer">这条推文</a>（转发链条起点为<a href="https://x.com/undefinedKi/status/2106479644354474463" target="_blank" rel="noreferrer">原推</a>） 📄 论文原文：arXiv <a href="https://arxiv.org/abs/2609.00006" target="_blank" rel="noreferrer">2609.00006</a> · <a href="https://arxiv.org/pdf/2609.00006" target="_blank" rel="noreferrer">PDF 直链</a> 整理于 2026-10-05 · 译文为个人学习摘要，版权归原作者</p></blockquote><h2 id="推文翻译" tabindex="-1">推文翻译 <a class="header-anchor" href="#推文翻译" aria-label="Permalink to &quot;推文翻译&quot;">​</a></h2><p><strong>原推</strong>（该推文的完整观点）：</p><blockquote><p>这可能是今年关于 AI Agent 最有用的一篇论文。</p><p>Wavestone AI Lab 的团队拆解了 Claude Code、Codex 以及另外 9 个编码 Agent，找出了每个优秀 Agent 赖以构建的<strong>七件套蓝图</strong>。</p><p>他们的定义：<strong>Agent = 模型 + Harness（驾驭层）</strong>。全部 11 个 Agent 都在构建这个 harness。</p></blockquote><p><strong>跟推</strong>（本笔记来源链接指向的这条）：</p><blockquote><p>论文：arxiv.org/pdf/2609.00006</p></blockquote><h2 id="论文信息" tabindex="-1">论文信息 <a class="header-anchor" href="#论文信息" aria-label="Permalink to &quot;论文信息&quot;">​</a></h2><ul><li><strong>标题</strong>：《Harness Engineering: Anatomy, Architecture, and Evolution of Coding Agents — A Source-Code Study of Eleven Systems》（驾驭层工程：编码 Agent 的解剖、架构与演化——十一个系统的源码研究）</li><li><strong>作者</strong>：Paul Barbaste、Tristan Darrigol、Germain Vu、Tom Wiltberger（InclusiveBrains / Wavestone AI Lab），2026 年 7 月</li><li><strong>研究对象</strong>：11 个生产级编码 harness——Claude Code、Codex CLI、Gemini CLI、Mistral Vibe、OpenHands、Aider、Mini-SWE-Agent、Hermes、Pi、OpenCode、<strong>OpenClaw</strong>，外加首个「元 harness」Omnigent 作对照</li></ul><h2 id="核心定义与摘要翻译" tabindex="-1">核心定义与摘要翻译 <a class="header-anchor" href="#核心定义与摘要翻译" aria-label="Permalink to &quot;核心定义与摘要翻译&quot;">​</a></h2><blockquote><p><strong>Agent 就是「模型 + harness」</strong>：harness 是那个把 LLM 与真实世界耦合起来的运行时——通过循环、工具、上下文管理、安全控制、编排和扩展 surface。「Harness engineering」（驾驭层工程）作为一门学科在 2026 年初被命名，本文为这门年轻的学科给出了迄今最全面的实证基础。</p></blockquote><p>论文对 11 个系统做了源码级解剖，映射出<strong>七个标准子系统</strong>（每个都给出最小与最大实现），并沉淀出 13 条横切观察与 29 个复现设计模式。</p><p><img src="'+s+'" alt="七个子系统与 90 行最小实现"></p><p><em>论文配图：七个子系统的最小观测形态（Agent loop / LLM 集成 / 工具与动作 / 记忆与上下文 / 安全与权限 / 编排 / 可扩展性），右侧是 Claude Code、Codex、Gemini CLI 等大多数系统共用的迭代循环：Prompt → LLM Call → Execute → Observe。</em></p><p>约 90 行的 <code>harness.py</code> 最小形态：<code>loop()</code>（调用→执行→观察→重复）、单一模板的 <code>llm.call()</code>、只有 bash 一个工具、完整保留的消息历史、<code>guard()</code> 步数与成本限制、<strong>刻意不做子 Agent</strong>、任意匹配对象皆可插入的 plugins。</p><h2 id="最有意思的发现" tabindex="-1">最有意思的发现 <a class="header-anchor" href="#最有意思的发现" aria-label="Permalink to &quot;最有意思的发现&quot;">​</a></h2><ul><li><strong>约 400 万行 Python/TypeScript/Rust 中</strong>：没有任何一个 Agent 运行时导入通用 Agentic 框架，也没有任何一个用向量嵌入检索代码——这个领域靠<strong>手写 async 循环 + 确定性检索</strong>运转；</li><li><strong>Skills 的采用率（9/11）超过了 MCP（8/11）</strong>；ACP 出现在 6 个系统中，并带来第三个新角色：harness hosting（驾驭层托管）；</li><li><strong>纵向对照样本</strong>：原有一批系统被重新 pin 而非替换，同一个季度内的 source diff 显示——<strong>趋同正在变成模仿</strong>，行为策略正从提示词散文迁移到配置文件；</li><li><strong>论文主旨</strong>：2026 年上半年，编码 harness 完成了从「工具」到「平台」的转身；</li><li>结尾给出 18 条设计建议和一个 90 行的最小可用 harness。</li></ul><h2 id="我的一点延伸" tabindex="-1">我的一点延伸 <a class="header-anchor" href="#我的一点延伸" aria-label="Permalink to &quot;我的一点延伸&quot;">​</a></h2><p>被拆解的 11 个系统里有 <strong>OpenClaw</strong>——就是我写过安装教程的那只「小龙虾🦞」，可以对照论文的七件套去看看它的实现取舍。论文的「模型 + harness」二分也和我给 <a href="https://github.com/Fyuan0206/good-harness" target="_blank" rel="noreferrer">good-harness</a>（&quot;给 AI 装马鞍&quot;教程）提 PR 时琢磨的问题完全同频：<strong>决定 Agent 上限的往往不是模型本身，而是那层把模型接住真实世界的运行时。</strong></p><ul><li><a href="/notes/">返回笔记目录</a></li></ul>',20)])])}const f=r(o,[["render",i]]);export{u as __pageData,f as default};
